function applyCalculation(value, callback) {
  return callback(value);
}
function runDouble(value) {
  return applyCalculation(value, (number) => number * 2);
}

function calculateWith(a, b, operation) {
  return operation(a, b);
}
function runByMode(a, b, mode) {
  const operation = mode === 'add' ? (x, y) => x + y : (x, y) => x * y;
  return calculateWith(a, b, operation);
}
